impl ManagedLocalAiStudio {
    pub(crate) fn show(&mut self, ui: &mut egui::Ui) -> bool {
        let mut preferences_changed = false;
        ui.group(|ui| {
            ui.strong("GameEngine-managed Local AI");
            ui.small(
                "GameEngine owns the pinned llama.cpp runtime, loopback process, health checks, and exact GGUF identity. Ollama, Modelfiles, compiler toolchains, manual ports, and llama-server commands are not required.",
            );

            let setup_status = self.display_setup_status();
            ui.horizontal_wrapped(|ui| {
                ui.label("Setup");
                ui.strong(setup_status_label(&setup_status));
                if self.task.is_some() {
                    ui.spinner();
                }
            });
            self.show_setup_action(ui, &setup_status);

            egui::CollapsingHeader::new("Advanced runtime override")
                .default_open(false)
                .show(ui, |ui| {
                    ui.small(
                        "Windows-native and WSL2 are separate benchmark environments. Ordinary setup does not require installing both.",
                    );
                    let previous = self.environment;
                    egui::ComboBox::from_id_salt("managed_local_environment")
                        .selected_text(self.environment.label())
                        .show_ui(ui, |ui| {
                            for environment in ManagedExecutionEnvironment::ALL {
                                ui.selectable_value(
                                    &mut self.environment,
                                    environment,
                                    environment.label(),
                                );
                            }
                        });
                    if self.environment != previous {
                        self.confirm_remove_wsl = false;
                        self.refresh_cached_state();
                        preferences_changed = true;
                    }
                    if self.environment == ManagedExecutionEnvironment::Wsl2Linux {
                        self.show_wsl_removal(ui);
                    }
                });

            ui.separator();
            ui.horizontal_wrapped(|ui| {
                ui.label("Managed models");
                if ui
                    .add_enabled(self.task.is_none(), egui::Button::new("Register existing GGUF…"))
                    .clicked()
                    && let Some(path) = rfd::FileDialog::new()
                        .add_filter("GGUF model", &["gguf"])
                        .pick_file()
                {
                    self.start_task(ManagedLocalTask::register_existing_gguf(
                        self.runtime.clone(),
                        path,
                    ));
                }
            });
            ui.small(
                "Model weights are never downloaded silently. Existing GGUF registration is an explicit import and does not modify the source bytes. Multi-model Download & Run approvals are frozen to the exact reviewed candidate set.",
            );

            let models = self.runtime.registered_models();
            match models {
                Ok(models) if models.is_empty() => {
                    ui.small("No managed GGUF models are registered yet.");
                }
                Ok(models) => {
                    let selected_text = models
                        .iter()
                        .find(|model| model.model_id == self.model_id)
                        .map(|model| model.display_name.as_str())
                        .unwrap_or("Select registered model");
                    ui.horizontal(|ui| {
                        ui.label("Model");
                        egui::ComboBox::from_id_salt("managed_local_model")
                            .selected_text(selected_text)
                            .width(280.0)
                            .show_ui(ui, |ui| {
                                for model in &models {
                                    if ui
                                        .selectable_label(
                                            self.model_id == model.model_id,
                                            &model.display_name,
                                        )
                                        .clicked()
                                    {
                                        self.model_id = model.model_id.clone();
                                        self.refresh_cached_state();
                                        preferences_changed = true;
                                    }
                                }
                            });
                    });
                    if let Some(model) = models.iter().find(|model| model.model_id == self.model_id)
                    {
                        ui.small(format!(
                            "Exact representation: {} · {} · quantization {} · source={} · license={}",
                            short_digest(&model.content_sha256),
                            format_bytes(model.size_bytes),
                            model.quantization.as_deref().unwrap_or("unreported"),
                            model.source.as_deref().unwrap_or("local file import"),
                            model.license.as_deref().unwrap_or("unreported"),
                        ));
                        self.show_environment_model_preparation(ui, model.size_bytes);
                    }
                }
                Err(error) => {
                    ui.small(format!("Managed model registry unavailable: {error}"));
                }
            }

            if self.selected_config().is_ok() {
                ui.small(format!(
                    "Ready · backend gameengine-managed-llama-cpp · llama.cpp {PINNED_LLAMA_CPP_TAG} ({PINNED_LLAMA_CPP_REVISION}) · {} · demand-driven loopback lifecycle",
                    self.environment.label(),
                ));
            } else if !self.model_id.trim().is_empty() {
                ui.small(
                    "Model is registered but this runtime/environment is not fully prepared yet. Setup remains fail-closed until runtime and model provenance are verifiable.",
                );
            }
        });
        preferences_changed
    }

}
